/**
 * Timeblock IndexedDB v1.0.0
 * Local-first persistence layer for a 24-hour, 15-minute timeblock tracker.
 *
 * Stores only populated blocks. The 96-slot timeline is generated by the UI.
 */

export const TIMEBLOCK_DB = Object.freeze({
  name: "TimeblockDB",
  version: 1,
  stores: Object.freeze({
    days: "days",
    timeblocks: "timeblocks",
    settings: "settings"
  }),
  settingsId: "app-settings",
  backupType: "timeblock-backup",
  backupFormatVersion: 1,
  appVersion: "1.0.0",
  maxTextLength: 2000
});

const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

export class TimeblockDB {
  #db = null;
  #writeQueue = Promise.resolve();
  #channel = null;
  #sourceId = crypto.randomUUID?.() ?? `${Date.now()}-${Math.random()}`;

  constructor({ onExternalChange } = {}) {
    this.onExternalChange = typeof onExternalChange === "function" ? onExternalChange : null;
    if ("BroadcastChannel" in globalThis) {
      this.#channel = new BroadcastChannel("timeblock-db-v1");
      this.#channel.addEventListener("message", event => {
        const message = event.data;
        if (!message || message.sourceId === this.#sourceId) return;
        this.onExternalChange?.(message);
      });
    }
  }

  async open() {
    if (this.#db) return this;
    if (!("indexedDB" in globalThis)) throw new Error("IndexedDB is not supported in this browser.");

    this.#db = await new Promise((resolve, reject) => {
      const request = indexedDB.open(TIMEBLOCK_DB.name, TIMEBLOCK_DB.version);

      request.onupgradeneeded = event => {
        const db = request.result;
        const transaction = request.transaction;
        if (event.oldVersion < 1) this.#createV1Schema(db, transaction);
      };

      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error ?? new Error("Unable to open TimeblockDB."));
      request.onblocked = () => reject(new Error("Database upgrade is blocked by another open tab."));
    });

    this.#db.onversionchange = () => {
      this.#db?.close();
      this.#db = null;
    };

    await this.#ensureDefaultSettings();
    return this;
  }

  close() {
    this.#channel?.close();
    this.#channel = null;
    this.#db?.close();
    this.#db = null;
  }

  #createV1Schema(db) {
    const days = db.createObjectStore(TIMEBLOCK_DB.stores.days, { keyPath: "date" });
    days.createIndex("updatedAt", "updatedAt", { unique: false });

    const blocks = db.createObjectStore(TIMEBLOCK_DB.stores.timeblocks, { keyPath: "id" });
    blocks.createIndex("date", "date", { unique: false });
    blocks.createIndex("dateSlot", ["date", "slot"], { unique: true });
    blocks.createIndex("updatedAt", "updatedAt", { unique: false });

    db.createObjectStore(TIMEBLOCK_DB.stores.settings, { keyPath: "id" });
  }

  async #ensureOpen() {
    if (!this.#db) await this.open();
  }

  #enqueueWrite(operation) {
    const run = this.#writeQueue.then(operation, operation);
    this.#writeQueue = run.catch(() => undefined);
    return run;
  }

  #transaction(storeNames, mode = "readonly") {
    if (!this.#db) throw new Error("TimeblockDB is not open.");
    return this.#db.transaction(storeNames, mode);
  }

  static request(request) {
    return new Promise((resolve, reject) => {
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error ?? new Error("IndexedDB request failed."));
    });
  }

  static transactionDone(transaction) {
    return new Promise((resolve, reject) => {
      transaction.oncomplete = () => resolve();
      transaction.onabort = () => reject(transaction.error ?? new Error("IndexedDB transaction aborted."));
      transaction.onerror = () => reject(transaction.error ?? new Error("IndexedDB transaction failed."));
    });
  }

  static localDate(date = new Date()) {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    return `${year}-${month}-${day}`;
  }

  static currentSlot(date = new Date()) {
    return date.getHours() * 4 + Math.floor(date.getMinutes() / 15);
  }

  static slotToTime(slot) {
    this.assertSlot(slot);
    const minutes = slot * 15;
    return `${String(Math.floor(minutes / 60)).padStart(2, "0")}:${String(minutes % 60).padStart(2, "0")}`;
  }

  static slotRange(slot) {
    this.assertSlot(slot);
    const start = this.slotToTime(slot);
    const endMinutes = (slot + 1) * 15;
    const end = endMinutes === 1440
      ? "00:00"
      : `${String(Math.floor(endMinutes / 60)).padStart(2, "0")}:${String(endMinutes % 60).padStart(2, "0")}`;
    return { start, end };
  }

  static blockId(date, slot) {
    this.assertDate(date);
    this.assertSlot(slot);
    return `${date}#${slot}`;
  }

  static assertDate(value) {
    if (!DATE_PATTERN.test(value)) throw new TypeError(`Invalid local date: ${value}`);
    const [year, month, day] = value.split("-").map(Number);
    const check = new Date(year, month - 1, day);
    if (check.getFullYear() !== year || check.getMonth() !== month - 1 || check.getDate() !== day) {
      throw new TypeError(`Invalid calendar date: ${value}`);
    }
  }

  static assertSlot(slot) {
    if (!Number.isInteger(slot) || slot < 0 || slot > 95) {
      throw new RangeError(`Slot must be an integer from 0 to 95. Received: ${slot}`);
    }
  }

  static normalizeText(text) {
    if (typeof text !== "string") throw new TypeError("Timeblock text must be a string.");
    const normalized = text.replace(/\r\n?/g, "\n").replace(/[\t ]+$/gm, "").replace(/\s+$/u, "");
    if (normalized.length > TIMEBLOCK_DB.maxTextLength) {
      throw new RangeError(`Timeblock text cannot exceed ${TIMEBLOCK_DB.maxTextLength} characters.`);
    }
    return normalized;
  }

  static generateTimeline(date, populatedBlocks = []) {
    this.assertDate(date);
    const bySlot = new Map(populatedBlocks.map(block => [block.slot, block]));
    const today = this.localDate();
    const nowSlot = this.currentSlot();

    return Array.from({ length: 96 }, (_, slot) => {
      const block = bySlot.get(slot) ?? null;
      const relation = date < today ? "past" : date > today ? "future" : slot < nowSlot ? "past" : slot === nowSlot ? "current" : "future";
      return {
        date,
        slot,
        id: this.blockId(date, slot),
        ...this.slotRange(slot),
        text: block?.text ?? "",
        hasEntry: Boolean(block),
        isPast: relation === "past",
        isCurrent: relation === "current",
        isFuture: relation === "future",
        revision: block?.revision ?? 0
      };
    });
  }

  async getDay(date) {
    await this.#ensureOpen();
    TimeblockDB.assertDate(date);
    const transaction = this.#transaction(TIMEBLOCK_DB.stores.days);
    return (await TimeblockDB.request(transaction.objectStore(TIMEBLOCK_DB.stores.days).get(date))) ?? null;
  }

  async getBlocksForDate(date) {
    await this.#ensureOpen();
    TimeblockDB.assertDate(date);
    const transaction = this.#transaction(TIMEBLOCK_DB.stores.timeblocks);
    const index = transaction.objectStore(TIMEBLOCK_DB.stores.timeblocks).index("dateSlot");
    const range = IDBKeyRange.bound([date, 0], [date, 95]);
    return TimeblockDB.request(index.getAll(range));
  }

  async getDayView(date) {
    const [day, blocks] = await Promise.all([this.getDay(date), this.getBlocksForDate(date)]);
    return {
      date,
      day,
      blocks,
      timeline: TimeblockDB.generateTimeline(date, blocks),
      entryCount: blocks.length,
      trackedMinutes: blocks.length * 15
    };
  }

  async getBlock(date, slot) {
    await this.#ensureOpen();
    const id = TimeblockDB.blockId(date, slot);
    const transaction = this.#transaction(TIMEBLOCK_DB.stores.timeblocks);
    return (await TimeblockDB.request(transaction.objectStore(TIMEBLOCK_DB.stores.timeblocks).get(id))) ?? null;
  }

  async saveBlock(date, slot, text, { expectedRevision } = {}) {
    await this.#ensureOpen();
    TimeblockDB.assertDate(date);
    TimeblockDB.assertSlot(slot);
    const normalizedText = TimeblockDB.normalizeText(text);
    if (!normalizedText.trim()) return this.deleteBlock(date, slot, { expectedRevision });

    return this.#enqueueWrite(async () => {
      const transaction = this.#transaction(
        [TIMEBLOCK_DB.stores.timeblocks, TIMEBLOCK_DB.stores.days],
        "readwrite"
      );
      const blocks = transaction.objectStore(TIMEBLOCK_DB.stores.timeblocks);
      const days = transaction.objectStore(TIMEBLOCK_DB.stores.days);
      const id = TimeblockDB.blockId(date, slot);
      const existing = await TimeblockDB.request(blocks.get(id));

      if (expectedRevision !== undefined && (existing?.revision ?? 0) !== expectedRevision) {
        transaction.abort();
        throw new Error(`Stale timeblock edit detected for ${id}. Expected revision ${expectedRevision}, found ${existing?.revision ?? 0}.`);
      }

      const now = new Date().toISOString();
      const record = {
        id,
        date,
        slot,
        text: normalizedText,
        createdAt: existing?.createdAt ?? now,
        updatedAt: now,
        revision: (existing?.revision ?? 0) + 1
      };
      blocks.put(record);

      const existingDay = await TimeblockDB.request(days.get(date));
      const entryCount = await TimeblockDB.request(blocks.index("date").count(IDBKeyRange.only(date)));
      days.put({
        date,
        createdAt: existingDay?.createdAt ?? now,
        updatedAt: now,
        entryCount,
        revision: (existingDay?.revision ?? 0) + 1
      });

      await TimeblockDB.transactionDone(transaction);

      const verified = await this.getBlock(date, slot);
      if (!verified || verified.revision !== record.revision || verified.text !== record.text) {
        throw new Error(`Save verification failed for ${id}.`);
      }

      this.#broadcast({ type: "BLOCK_UPDATED", date, slot, revision: record.revision });
      return verified;
    });
  }

  async deleteBlock(date, slot, { expectedRevision } = {}) {
    await this.#ensureOpen();
    TimeblockDB.assertDate(date);
    TimeblockDB.assertSlot(slot);

    return this.#enqueueWrite(async () => {
      const transaction = this.#transaction(
        [TIMEBLOCK_DB.stores.timeblocks, TIMEBLOCK_DB.stores.days],
        "readwrite"
      );
      const blocks = transaction.objectStore(TIMEBLOCK_DB.stores.timeblocks);
      const days = transaction.objectStore(TIMEBLOCK_DB.stores.days);
      const id = TimeblockDB.blockId(date, slot);
      const existing = await TimeblockDB.request(blocks.get(id));

      if (!existing) {
        await TimeblockDB.transactionDone(transaction);
        return false;
      }
      if (expectedRevision !== undefined && existing.revision !== expectedRevision) {
        transaction.abort();
        throw new Error(`Stale timeblock delete detected for ${id}. Expected revision ${expectedRevision}, found ${existing.revision}.`);
      }

      blocks.delete(id);
      const remainingCount = await TimeblockDB.request(blocks.index("date").count(IDBKeyRange.only(date)));
      const existingDay = await TimeblockDB.request(days.get(date));

      if (remainingCount <= 0) {
        days.delete(date);
      } else {
        const now = new Date().toISOString();
        days.put({
          ...existingDay,
          date,
          updatedAt: now,
          entryCount: remainingCount,
          revision: (existingDay?.revision ?? 0) + 1
        });
      }

      await TimeblockDB.transactionDone(transaction);
      if (await this.getBlock(date, slot)) throw new Error(`Delete verification failed for ${id}.`);

      this.#broadcast({ type: "BLOCK_DELETED", date, slot, revision: existing.revision + 1 });
      return true;
    });
  }

  async listRecordedDays({ newestFirst = true } = {}) {
    await this.#ensureOpen();
    const transaction = this.#transaction(TIMEBLOCK_DB.stores.days);
    const records = await TimeblockDB.request(transaction.objectStore(TIMEBLOCK_DB.stores.days).getAll());
    return records.sort((a, b) => newestFirst ? b.date.localeCompare(a.date) : a.date.localeCompare(b.date));
  }

  async getSettings() {
    await this.#ensureOpen();
    const transaction = this.#transaction(TIMEBLOCK_DB.stores.settings);
    return (await TimeblockDB.request(transaction.objectStore(TIMEBLOCK_DB.stores.settings).get(TIMEBLOCK_DB.settingsId))) ?? null;
  }

  async saveSettings(patch) {
    await this.#ensureOpen();
    const allowed = new Set(["timeFormat", "weekStartsOn", "autoScrollToNow"]);
    for (const key of Object.keys(patch)) {
      if (!allowed.has(key)) throw new Error(`Unsupported setting: ${key}`);
    }

    return this.#enqueueWrite(async () => {
      const current = await this.getSettings();
      const now = new Date().toISOString();
      const record = {
        ...current,
        ...patch,
        id: TIMEBLOCK_DB.settingsId,
        createdAt: current?.createdAt ?? now,
        updatedAt: now
      };
      const transaction = this.#transaction(TIMEBLOCK_DB.stores.settings, "readwrite");
      transaction.objectStore(TIMEBLOCK_DB.stores.settings).put(record);
      await TimeblockDB.transactionDone(transaction);
      this.#broadcast({ type: "SETTINGS_UPDATED" });
      return this.getSettings();
    });
  }

  async #ensureDefaultSettings() {
    const current = await this.getSettings();
    if (current) return current;
    const now = new Date().toISOString();
    const defaults = {
      id: TIMEBLOCK_DB.settingsId,
      timeFormat: "24h",
      weekStartsOn: 1,
      autoScrollToNow: true,
      createdAt: now,
      updatedAt: now
    };
    const transaction = this.#transaction(TIMEBLOCK_DB.stores.settings, "readwrite");
    transaction.objectStore(TIMEBLOCK_DB.stores.settings).put(defaults);
    await TimeblockDB.transactionDone(transaction);
    return defaults;
  }

  async exportBackup() {
    await this.#ensureOpen();
    const transaction = this.#transaction([
      TIMEBLOCK_DB.stores.days,
      TIMEBLOCK_DB.stores.timeblocks,
      TIMEBLOCK_DB.stores.settings
    ]);
    const [days, timeblocks, settings] = await Promise.all([
      TimeblockDB.request(transaction.objectStore(TIMEBLOCK_DB.stores.days).getAll()),
      TimeblockDB.request(transaction.objectStore(TIMEBLOCK_DB.stores.timeblocks).getAll()),
      TimeblockDB.request(transaction.objectStore(TIMEBLOCK_DB.stores.settings).getAll())
    ]);

    const payload = {
      type: TIMEBLOCK_DB.backupType,
      formatVersion: TIMEBLOCK_DB.backupFormatVersion,
      appVersion: TIMEBLOCK_DB.appVersion,
      exportedAt: new Date().toISOString(),
      counts: { days: days.length, timeblocks: timeblocks.length },
      days: days.sort((a, b) => a.date.localeCompare(b.date)),
      timeblocks: timeblocks.sort((a, b) => a.date.localeCompare(b.date) || a.slot - b.slot),
      settings
    };
    return { payload, json: JSON.stringify(payload, null, 2) };
  }

  static validateBackup(payload) {
    if (!payload || typeof payload !== "object") throw new Error("Backup must be a JSON object.");
    if (payload.type !== TIMEBLOCK_DB.backupType) throw new Error("Unsupported backup type.");
    if (payload.formatVersion !== TIMEBLOCK_DB.backupFormatVersion) throw new Error("Unsupported backup format version.");
    if (!Array.isArray(payload.timeblocks) || !Array.isArray(payload.days) || !Array.isArray(payload.settings)) {
      throw new Error("Backup is missing required arrays.");
    }

    const ids = new Set();
    for (const block of payload.timeblocks) {
      this.assertDate(block.date);
      this.assertSlot(block.slot);
      const expectedId = this.blockId(block.date, block.slot);
      if (block.id !== expectedId) throw new Error(`Invalid block ID: ${block.id}`);
      if (ids.has(block.id)) throw new Error(`Duplicate block ID: ${block.id}`);
      ids.add(block.id);
      this.normalizeText(block.text);
      if (!Number.isInteger(block.revision) || block.revision < 1) throw new Error(`Invalid revision for ${block.id}`);
      if (!Date.parse(block.createdAt) || !Date.parse(block.updatedAt)) throw new Error(`Invalid timestamp for ${block.id}`);
    }

    return true;
  }

  async restoreBackup(payload, { mode = "replace" } = {}) {
    await this.#ensureOpen();
    TimeblockDB.validateBackup(payload);
    if (!new Set(["replace", "merge"]).has(mode)) throw new Error("Restore mode must be 'replace' or 'merge'.");

    const safetySnapshot = (await this.exportBackup()).payload;

    try {
      await this.#enqueueWrite(async () => {
        const transaction = this.#transaction([
          TIMEBLOCK_DB.stores.days,
          TIMEBLOCK_DB.stores.timeblocks,
          TIMEBLOCK_DB.stores.settings
        ], "readwrite");
        const days = transaction.objectStore(TIMEBLOCK_DB.stores.days);
        const blocks = transaction.objectStore(TIMEBLOCK_DB.stores.timeblocks);
        const settings = transaction.objectStore(TIMEBLOCK_DB.stores.settings);

        if (mode === "replace") {
          days.clear();
          blocks.clear();
          settings.clear();
        }

        for (const record of payload.days) days.put(record);
        for (const record of payload.timeblocks) blocks.put(record);
        for (const record of payload.settings) settings.put(record);
        await TimeblockDB.transactionDone(transaction);
      });

      await this.#rebuildDayMetadata();
      const verification = await this.exportBackup();
      if (verification.payload.counts.timeblocks < payload.timeblocks.length && mode === "replace") {
        throw new Error("Restore verification failed: timeblock count mismatch.");
      }
      this.#broadcast({ type: "DATABASE_RESTORED", mode });
      return { restored: true, safetySnapshot, counts: verification.payload.counts };
    } catch (error) {
      await this.#replaceAllFromValidatedBackup(safetySnapshot);
      throw new Error(`Restore failed and original data was reinstated: ${error.message}`);
    }
  }

  async #replaceAllFromValidatedBackup(payload) {
    TimeblockDB.validateBackup(payload);
    await this.#enqueueWrite(async () => {
      const transaction = this.#transaction([
        TIMEBLOCK_DB.stores.days,
        TIMEBLOCK_DB.stores.timeblocks,
        TIMEBLOCK_DB.stores.settings
      ], "readwrite");
      const days = transaction.objectStore(TIMEBLOCK_DB.stores.days);
      const blocks = transaction.objectStore(TIMEBLOCK_DB.stores.timeblocks);
      const settings = transaction.objectStore(TIMEBLOCK_DB.stores.settings);
      days.clear();
      blocks.clear();
      settings.clear();
      payload.days.forEach(record => days.put(record));
      payload.timeblocks.forEach(record => blocks.put(record));
      payload.settings.forEach(record => settings.put(record));
      await TimeblockDB.transactionDone(transaction);
    });
  }

  async #rebuildDayMetadata() {
    const recordedDays = new Map();
    const transaction = this.#transaction(TIMEBLOCK_DB.stores.timeblocks);
    const blocks = await TimeblockDB.request(transaction.objectStore(TIMEBLOCK_DB.stores.timeblocks).getAll());
    for (const block of blocks) {
      const state = recordedDays.get(block.date) ?? { count: 0, createdAt: block.createdAt, updatedAt: block.updatedAt };
      state.count += 1;
      if (block.createdAt < state.createdAt) state.createdAt = block.createdAt;
      if (block.updatedAt > state.updatedAt) state.updatedAt = block.updatedAt;
      recordedDays.set(block.date, state);
    }

    await this.#enqueueWrite(async () => {
      const write = this.#transaction(TIMEBLOCK_DB.stores.days, "readwrite");
      const days = write.objectStore(TIMEBLOCK_DB.stores.days);
      days.clear();
      for (const [date, state] of recordedDays) {
        days.put({
          date,
          createdAt: state.createdAt,
          updatedAt: state.updatedAt,
          entryCount: state.count,
          revision: 1
        });
      }
      await TimeblockDB.transactionDone(write);
    });
  }

  #broadcast(message) {
    this.#channel?.postMessage({ ...message, sourceId: this.#sourceId, sentAt: new Date().toISOString() });
  }
}

/**
 * Debounced autosave helper for textareas/inputs.
 * Call controller.schedule(date, slot, text, revision) on input.
 */
export function createAutosaveController(database, { delay = 500, onStateChange } = {}) {
  const pending = new Map();
  const notify = (state, detail = {}) => onStateChange?.({ state, ...detail });

  return {
    schedule(date, slot, text, expectedRevision) {
      const id = TimeblockDB.blockId(date, slot);
      clearTimeout(pending.get(id)?.timer);
      notify("pending", { id, date, slot });

      const timer = setTimeout(async () => {
        pending.delete(id);
        notify("saving", { id, date, slot });
        try {
          const result = await database.saveBlock(date, slot, text, { expectedRevision });
          notify("saved", { id, date, slot, record: result });
        } catch (error) {
          notify("error", { id, date, slot, error });
        }
      }, delay);

      pending.set(id, { timer, date, slot });
    },

    cancel(date, slot) {
      const id = TimeblockDB.blockId(date, slot);
      const item = pending.get(id);
      if (item) clearTimeout(item.timer);
      pending.delete(id);
    },

    cancelAll() {
      for (const item of pending.values()) clearTimeout(item.timer);
      pending.clear();
    },

    get pendingCount() {
      return pending.size;
    }
  };
}

export default TimeblockDB;
